const prompt = msg.prompt || (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload));
let cmd = `agy -p ${JSON.stringify(prompt)} --dangerously-skip-permissions`;
if (msg.schema) {
    const schemaStr = typeof msg.schema === 'object' ? JSON.stringify(msg.schema) : msg.schema;
    cmd += ` --json-schema ${JSON.stringify(schemaStr)} --output-format json`;
}
msg.payload = cmd;
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}
let result = parsed.structured_output;
if (!result && parsed.response) {
    try { result = typeof parsed.response === 'string' ? JSON.parse(parsed.response) : parsed.response; } catch (e) { result = parsed.response; }
}
msg.payload = result || parsed;
return msg;

let task;
try { task = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (err) { task = {}; }
const routes = {
  CLASSIFY_FILE: {
    prompt: t => `請將檔案「${t.input.files?.[0]?.filename || ''}」分類到 Installers、Documents、Archives、Media 或 Others，並說明理由。`,
    schema: { type: 'object', properties: { category: { type: 'string', enum: ['Installers','Documents','Archives','Media','Others'] }, reason: { type: 'string' } }, required: ['category','reason'] }
  },
  PERF_RCA: {
    prompt: t => `請根據系統指標分析目前狀態：${JSON.stringify(t.input)}`,
    schema: { type: 'object', properties: { severity: { type: 'string', enum: ['INFO','WARNING','CRITICAL'] }, root_cause: { type: 'string' }, suggested_action: { type: 'string' } }, required: ['severity','root_cause','suggested_action'] }
  }
};
const route = routes[task.task_type];
if (!task.task_id || !task.input || !route) {
    msg.payload = { status: 'UNSUPPORTED_TASK', task_id: task.task_id || null, reason: '缺少必要欄位或不支援的 task_type' };
    return [null, msg];
}
msg.taskInfo = task;
msg.prompt = route.prompt(task);
msg.schema = route.schema;
return [msg, null];

let parsed;
try { parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (e) { parsed = { response: msg.payload }; }
let result = parsed.structured_output || parsed.response || parsed;
if (typeof result === 'string') { try { result = JSON.parse(result); } catch (e) {} }
msg.decision = result;
msg.payload = { ...(msg.taskInfo || {}), decision: result };
return msg;
